// machines/plaits: the SAM speech synth's sample loop (lib/sam_speech_synth.c), hand-written SISD kernel.
// Generated by lib/gen_sam_kernel.py; do not edit by hand.
//
// sam_kernel(SAMSpeechSynth *s, const float *k, float *excitation, float *output, int size): k[0] = the frequency
//   interpolator's increment, k[1..3] = the formant frequencies (unsigned ints), k[4..6] = the same as floats,
//   k[7..9] = the formant amplitudes. Writes excitation and output and the state back (phase_, frequency_,
//   pulse_next_sample_, pulse_lp_, formant_phase_[3]), bit-identical to selcc's code of the C loop (-DPL_SAM_C)
//   (tests/plaits/test_sam_kernel.py).
//
// State on return: R0-R8, R12, I4 and the flags change; every other register is as on entry (R9-R11, R13-R15 saved
// above I7; I0, I1, I2, M6, L0, L1, L2, L4 pushed through R0, M6 = 1 and L0 = L1 = L2 = L4 = 0 set here). No SIMD.
// ABI: as the other kernels (lib/wavetable_sm.s). Assembled under .COMPRESS; integer additions in their 48-bit form.

.SECTION/PM seg_pmco;
.GLOBAL sam_kernel.;
.EXTERN pl_lut_sine.;
.COMPRESS;

sam_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L4 = 0;
    I7=MODIFY (I7,-18)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I2 = R4;                                            // s
    I4 = R8;                                            // k
    I0 = R12;                                           // excitation
    R0 = DM(1, I6);                                     // output
    I1 = R0;
    R0 = DM(0, I4);
    DM(7, I7) = R0;
    R0 = DM(1, I4);
    DM(8, I7) = R0;
    R0 = DM(2, I4);
    DM(9, I7) = R0;
    R0 = DM(3, I4);
    DM(10, I7) = R0;
    R0 = DM(4, I4);
    DM(11, I7) = R0;
    R0 = DM(5, I4);
    DM(12, I7) = R0;
    R0 = DM(6, I4);
    DM(13, I7) = R0;
    R0 = DM(7, I4);
    DM(14, I7) = R0;
    R0 = DM(8, I4);
    DM(15, I7) = R0;
    R0 = DM(9, I4);
    DM(16, I7) = R0;
    R0 = pl_lut_sine.;
    DM(18, I7) = R0;
    R0 = DM(2, I6);                                     // size
    DM(17, I7) = R0;
    R15 = DM(0, I2);                                    // phase_
    R9 = DM(1, I2);                                     // frequency_ (the interpolator's value)
    R14 = DM(2, I2);                                    // pulse_next_sample
    R13 = DM(3, I2);                                    // pulse_lp_
    R12 = DM(4, I2);                                    // formant_phase_[0..2]
    R11 = DM(5, I2);
    R10 = DM(6, I2);
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _sak_done;
_sak_loop:
    R8 = PASS R14;                                      // pulse_this_sample = pulse_next_sample
    R14 = 0;                                            // pulse_next_sample = 0.0f
    R0 = DM(7, I7);
    F9 = F9 + F0;                                       // f = fm.Next()
    F15 = F15 + F9;                                     // phase_ += f
    R0 = 0x3F800000;
    COMP(F15, F0);                                      // phase_ >= 1.0f
    IF LT JUMP _sak_nr;
    F15 = F15 - F0;                                     // phase_ -= 1.0f
    R4 = 0x40000000;
    F1 = RECIPS F9;                                     // t = phase_ / f (selcc division)
    F2 = F9 * F1;
    F2 = F4 - F2;
    F1 = F1 * F2;
    F2 = F9 * F1;
    F2 = F4 - F2;
    F1 = F1 * F2;
    F4 = F15 * F1;
    F2 = F9 * F4;
    F2 = F15 - F2;
    F2 = F2 * F1;
    F3 = F4 + F2;
    R1 = DM(11, I7);
    F1 = F3 * F1;                                       // formant_phase_ = (unsigned int)(int)(t * formant_frequency_f)
    R12 = TRUNC F1;
    R1 = DM(12, I7);
    F1 = F3 * F1;                                       // formant_phase_ = (unsigned int)(int)(t * formant_frequency_f)
    R11 = TRUNC F1;
    R1 = DM(13, I7);
    F1 = F3 * F1;                                       // formant_phase_ = (unsigned int)(int)(t * formant_frequency_f)
    R10 = TRUNC F1;
    R0 = 0x3F000000;
    F0 = F0 * F3;                                       // pulse_this_sample -= ThisBlepSample(t)
    F0 = F0 * F3;
    F8 = F8 - F0;
    R0 = 0x3F800000;
    F1 = F0 - F3;                                       // pulse_next_sample -= NextBlepSample(t)
    R0 = 0xBF000000;
    F0 = F0 * F1;
    F0 = F0 * F1;
    F14 = F14 - F0;
    JUMP _sak_ns;
_sak_nr:
    R1 = DM(8, I7);
    .NOCOMPRESS;
    R12 = R12 + R1;                                     // formant_phase_ += formant_frequency
    .COMPRESS;
    R1 = DM(9, I7);
    .NOCOMPRESS;
    R11 = R11 + R1;                                     // formant_phase_ += formant_frequency
    .COMPRESS;
    R1 = DM(10, I7);
    .NOCOMPRESS;
    R10 = R10 + R1;                                     // formant_phase_ += formant_frequency
    .COMPRESS;
_sak_ns:
    F14 = F14 + F15;                                    // pulse_next_sample += phase_
    R0 = 0x3F000000;
    F0 = F8 - F0;                                       // d = pulse_this_sample - 0.5f - pulse_lp_
    F0 = F0 - F13;
    R1 = 0x41800000;
    F1 = F1 * F9;                                       // pulse_lp_ += minf(16.0f * f, 1.0f) * d
    R2 = 0x3F800000;
    COMP(F1, F2);
    IF GE R1 = R2 OR R2;
    F1 = F1 * F0;
    F13 = F13 + F1;
    DM(I0, M6) = R0;                                    // excitation[n] = d
    R6 = -23;
    R7 = DM(18, I7);
    R3 = 0;                                             // sum = 0.0f
    R0 = LSHIFT R12 BY R6;                              // sum += sine[formant_phase_ >> 23] * formant_amplitude
    R0 = LSHIFT R0 BY 2;
    .NOCOMPRESS;
    R0 = R0 + R7;
    .COMPRESS;
    I4 = R0;
    R1 = DM(14, I7);
    R4 = 0;                                             // (DAG gap)
    R5 = 0;
    R0 = DM(I4, M5);
    F0 = F0 * F1;
    F3 = F3 + F0;
    R0 = LSHIFT R11 BY R6;                              // sum += sine[formant_phase_ >> 23] * formant_amplitude
    R0 = LSHIFT R0 BY 2;
    .NOCOMPRESS;
    R0 = R0 + R7;
    .COMPRESS;
    I4 = R0;
    R1 = DM(15, I7);
    R4 = 0;                                             // (DAG gap)
    R5 = 0;
    R0 = DM(I4, M5);
    F0 = F0 * F1;
    F3 = F3 + F0;
    R0 = LSHIFT R10 BY R6;                              // sum += sine[formant_phase_ >> 23] * formant_amplitude
    R0 = LSHIFT R0 BY 2;
    .NOCOMPRESS;
    R0 = R0 + R7;
    .COMPRESS;
    I4 = R0;
    R1 = DM(16, I7);
    R4 = 0;                                             // (DAG gap)
    R5 = 0;
    R0 = DM(I4, M5);
    F0 = F0 * F1;
    F3 = F3 + F0;
    R0 = 0x3F800000;
    F0 = F0 - F15;                                      // sum *= (1.0f - phase_)
    F3 = F3 * F0;
    DM(I1, M6) = R3;                                    // output[n] = sum
    R0 = DM(17, I7);
    R1 = 1;
    .NOCOMPRESS;
    R0 = R0 - R1;
    .COMPRESS;
    DM(17, I7) = R0;
    IF NE JUMP _sak_loop;
_sak_done:
    DM(0, I2) = R15;
    DM(1, I2) = R9;
    DM(2, I2) = R14;
    DM(3, I2) = R13;
    DM(4, I2) = R12;
    DM(5, I2) = R11;
    DM(6, I2) = R10;
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,18)(NW);
    L4 = DM(1, I7);
    L2 = DM(2, I7);
    L1 = DM(3, I7);
    L0 = DM(4, I7);
    M6 = DM(5, I7);
    I2 = DM(6, I7);
    I1 = DM(7, I7);
    I0 = DM(8, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
